import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query'
import { useState } from 'react'
import { getMetaApp, regenerateVerifyToken } from '../../api/settings'

/** The webhook verify token: revealed, copied, or regenerated.
 *
 * Generated by the server and never typed, which is why this is not an input.
 * Shared between the Settings card and step 9 of the guided setup so there is
 * only one place that can regenerate it.
 */
export function VerifyTokenField() {
  const queryClient = useQueryClient()
  const { data } = useQuery({ queryKey: ['meta-app'], queryFn: getMetaApp, retry: false })
  const [showToken, setShowToken] = useState(false)
  const [note, setNote] = useState<string | null>(null)

  const regenerate = useMutation({
    mutationFn: regenerateVerifyToken,
    onSuccess: (result) => {
      setShowToken(true)
      setNote(result?.note ?? 'A new verify token was generated.')
      queryClient.invalidateQueries({ queryKey: ['meta-app'] })
    },
  })

  return (
    <>
      <p className="muted small">
        Generated here, pasted into Meta&rsquo;s webhook configuration. Regenerating
        invalidates the old one, so the subscription has to be verified again.
      </p>
      <div className="row">
        <code className="copy-field-value">
          {showToken ? data?.verify_token || '—' : '••••••••••••••••••••'}
        </code>
        <button className="link" onClick={() => setShowToken((v) => !v)}>
          {showToken ? 'Hide' : 'Reveal'}
        </button>
        <button
          className="link"
          onClick={() => data?.verify_token && navigator.clipboard?.writeText(data.verify_token)}
        >
          Copy
        </button>
        <button
          className="secondary"
          disabled={regenerate.isPending}
          onClick={() => regenerate.mutate()}
        >
          Regenerate
        </button>
      </div>
      {regenerate.error && (
        <p className="err small" role="alert">{(regenerate.error as Error).message}</p>
      )}
      {note && !regenerate.error && <p className="ok small">{note}</p>}
    </>
  )
}
